#pragma once

#include <string>
#include <sstream>
#include <vector>

namespace vitalgrid {

enum class AlertSeverity {
    NOMINAL,
    WARNING,
    CRITICAL
};

inline std::string to_string(AlertSeverity severity) {
    switch (severity) {
        case AlertSeverity::CRITICAL: return "CRITICAL";
        case AlertSeverity::WARNING:  return "WARNING";
        case AlertSeverity::NOMINAL:
        default:                      return "NOMINAL";
    }
}

/**
 * @brief Sub-JSON clinical alert generated by Flight Surgeon AI
 */
struct ClinicalAlert {
    AlertSeverity status = AlertSeverity::NOMINAL;
    std::string trigger_metric;
    std::string trigger_value;
    std::string threshold_limit;
    std::string diagnosis;
    std::string tactical_action;
    std::string timestamp;

    std::string to_json() const {
        std::ostringstream ss;
        ss << "{"
           << "\"type\":\"CLINICAL_ALERT\","
           << "\"status\":\"" << to_string(status) << "\","
           << "\"trigger_metric\":\"" << escape_json(trigger_metric) << "\","
           << "\"trigger_value\":\"" << escape_json(trigger_value) << "\","
           << "\"threshold_limit\":\"" << escape_json(threshold_limit) << "\","
           << "\"diagnosis\":\"" << escape_json(diagnosis) << "\","
           << "\"tactical_action\":\"" << escape_json(tactical_action) << "\","
           << "\"timestamp\":\"" << escape_json(timestamp) << "\""
           << "}";
        return ss.str();
    }

private:
    static std::string escape_json(const std::string& input) {
        std::ostringstream ss;
        for (char c : input) {
            if (c == '"') ss << "\\\"";
            else if (c == '\\') ss << "\\\\";
            else if (c == '\b') ss << "\\b";
            else if (c == '\f') ss << "\\f";
            else if (c == '\n') ss << "\\n";
            else if (c == '\r') ss << "\\r";
            else if (c == '\t') ss << "\\t";
            else ss << c;
        }
        return ss.str();
    }
};

} // namespace vitalgrid
